  'tour.start': 'Начать пользоваться',
  'tour.again': 'Пройти обучение заново',
  'tour.welcome': 'Привет, {name}!',
  'tour.welcomeBody': 'Это ваше общее пространство на двоих: дела, покупки, календарь, деньги, планы и маленькие радости. Всё, что добавляет один, сразу видит второй. Сначала выбери язык — дальше покажем самое главное за минуту.',
  'tour.today': 'Экран «Сегодня»',
  'tour.todayBody': 'Главный экран дня: события, задачи и покупки на сегодня, ваш статус («работаю», «за рулём») и настроение. Открывай его утром — и сразу понятно, что впереди.',
  'tour.tabs': 'Панель внизу и «Ещё»',
  'tour.tabsBody': 'Внизу — четыре раздела, которыми ты пользуешься чаще всего. Все остальные (бюджет, рецепты, поездки, вишлист и другие) живут во вкладке «Ещё».',
  'tour.tabsTip': 'Какие разделы будут внизу, выбираешь сам: Настройки → Нижняя панель.',
  'tour.add': 'Как добавлять',
  'tour.addBody': 'В каждом разделе есть «+» вверху или строка быстрого ввода. Пиши как удобно: «молоко, хлеб, сыр» сразу разложится по отделам, а «позвонить маме завтра в 18:00» станет задачей с датой и временем.',
  'tour.addTip': 'Ссылку можно просто вставить — приложение само подтянет название и картинку.',
  'tour.swipe': 'Жесты',
  'tour.swipeBody': 'Строку можно смахнуть: влево — удалить, вправо — отметить сделанным или купленным. Нажатие на строку открывает подробности.',
  'tour.swipeTip': 'Удалили случайно? Внизу на пару секунд появится кнопка «Отменить».',
  'tour.privacy': 'Личное и сюрпризы',
  'tour.privacyBody': 'Любую запись можно сделать «только для меня» или сюрпризом: партнёр не увидит её до выбранной даты. Подарки из вишлиста, которые ты готовишь, видишь только ты.',
  'tour.us': 'Раздел «Мы»',
  'tour.usBody': 'Ваш общий огонёк: любое дело вместе засчитывает день, растут талисман пары и дерево отношений. Без давления — пропуски прощаются, уровни не падают. Здесь же настроение и маленькие задания на день.',
  'tour.calendar': 'Календарь',
  'tour.calendarBody': 'Общие события и дни рождения. Можно подключить Google Календарь и Google Задачи — тогда всё синхронизируется в обе стороны: Настройки → Google.',
  'tour.install': 'Поставь на экран «Домой»',
  'tour.installIos': 'Так приложение открывается как обычное и может присылать уведомления. В Safari: кнопка «Поделиться» → «На экран Домой». Потом открой его с иконки и включи уведомления в настройках.',
  'tour.installAndroid': 'Так приложение открывается как обычное и может присылать уведомления. В Chrome: меню ⋮ → «Установить приложение». Потом открой его с иконки и включи уведомления в настройках.',
  'tour.settings': 'Всё настраивается',
  'tour.settingsBody': 'В настройках — тема и вид, порядок разделов, языки, уведомления, валюта, категории и интеграции. Если что-то забудешь, это обучение можно пройти ещё раз там же.',
