  'pair.inviteFriends': 'Пригласить другую пару',
  'pair.shareText': '{name} зовёт тебя в наш Family Hub 💞',
  'pair.shareFriends': 'Попробуйте Family Hub — общее приложение для пар 💞',
  'pair.partnerHint': 'Партнёр откроет ссылку, войдёт или зарегистрируется — и вы окажетесь в одной паре.',
  'pair.friendsHint': 'Пары, которые придут по вашей ссылке, засчитываются вам в коллекции.',
  'faq.title': 'Вопросы и ответы',
  'faq.q1': 'Кто видит мои записи?',
  'faq.a1': 'Всё, что вы добавляете, видите вы оба. Запись «Только я» видите только вы, а сюрприз партнёр увидит лишь в выбранный день — это проверяет сам сервер, а не только приложение.',
  'faq.q2': 'Как пригласить партнёра?',
  'faq.a2': 'Настройки → Пара и аккаунт → «Отправить приглашение партнёру». Партнёр откроет ссылку, войдёт — и вы в одной паре. Код можно ввести и вручную.',
  'faq.q3': 'Работает ли без интернета?',
  'faq.a3': 'Да. Всё сохраняется на телефоне и отправится, как только появится сеть.',
  'faq.q4': 'Почему не приходят уведомления?',
  'faq.a4': 'Поставьте приложение на экран «Домой», откройте его оттуда и включите уведомления: Настройки → Уведомления и связь → Уведомления. На iPhone без этого iOS уведомления не пропускает. Или выберите доставку в Telegram.',
  'faq.q5': 'Что такое огонёк и талисман?',
  'faq.a5': 'Каждый день, когда вы делаете что-то вместе, огонёк горит, а талисман растёт. Пропуски прикрывают заморозки, в поездках огонёк сам на паузе. Всё это можно выключить: Настройки → Игра и награды.',
  'faq.q6': 'Что такое коллекция?',
  'faq.a6': 'Темы (в том числе страны с флагами), талисманы, шапочки, рамки, огоньки, сцены, открытки и копилки. Часть открыта сразу, остальное открывается за дела в приложении или покупается один раз — сразу для вас обоих.',
  'faq.q7': 'Можно ли выгрузить данные?',
  'faq.a7': 'Да: Настройки → Данные и помощь → Данные → «Экспорт в файл». Получится файл со всеми вашими записями.',
  'faq.q8': 'Как удалить свои данные?',
  'faq.a8': 'Настройки → Данные и помощь → «Удалить мои данные». Удалятся ваши личные записи, и вы выйдете из пары; если в паре больше никого нет — удалится всё.',
