  importRecipe: 'Import recipe from link', importFail: 'Couldn’t read the recipe — fill it in by hand', steps: 'Steps', stepsHint: 'One step per line', cookMode: 'Cooking mode', stepN: 'Step {n} of {m}', minutesN: '{n} min', servingsN: '{n} serv.', next: 'Next', prev: 'Back', bonAppetit: 'Bon appétit! 🍽️', upcomingDays: 'Coming up', device: 'This device', 'platform.auto': 'Auto · {p}', 'platform.ios': 'iPhone', 'platform.android': 'Android', deviceHint: 'The layout (sidebar and full-width columns on an iPad or a computer), shortcut guides, widgets and the find-my-phone button adapt to the device. This setting is for this device only.', openFindHub: 'Open Find Hub', installHintAndroid: 'Open in Chrome → ⋮ → Install app (or Add to Home screen). It opens without the address bar, shows up in the Share menu and in a long-press on the icon.', pushDeniedAndroid: 'Blocked — allow them in Chrome: lock icon by the address → Notifications', presetsAndroid: 'Automations', presetsHintAndroid: 'With the free MacroDroid app from Google Play: the phone sets statuses, records Google Wallet payments and reads lists for you. Adding to lists is easiest from the Share menu and a long-press on the Family Hub icon.', quickActions: 'Quick actions', quickActionsIntro: 'On Android, instead of the Scriptable widget:', qa1: 'Long-press the Family Hub icon → Groceries, Tasks, Budget or Inbox.', qa2: 'Drag any of them to the Home screen for its own icon.', qa3: 'In any app, Share → Family Hub: a link, text or song lands wherever you pick.', shareTitle: 'Save to Family Hub', shareWhere: 'Where to save?', urlStart: 'Start', urlEnd: 'End', statusSourceTitle: 'Where the status comes from', statusSource: 'Phone automations set it for you: Sleep focus → 😴, car connects → 🚗, arrive at work → 💼 — and clear it when the focus turns off or you leave. Set up once in Ready-made shortcuts. When you’re both doing the same thing it shows as one shared status 💞. By hand: tap your status on Today.', autoCode: 'Automation code', autoCodeHint: 'In the automation set event = {id}. To clear it by itself, add a second one with event = {id} and end = 1.', ownPhoto: 'Own photo', fromLink: 'From link', noPicture: 'No picture', noPreview: 'The link has no picture — add your own photo', photoFail: 'Couldn’t load the photo', caption: 'Caption', linkPreviews: 'Pictures for links', linkPreviewsHint: 'A pasted link pulls in the page’s picture and title. If that fails, set your own photo and caption.',
  clearData: 'Delete test data', clearConfirm: 'Delete all records (tasks, groceries, expenses, movies…)? Settings stay.',
  clearConfirmSync: 'Delete all records for both of you — tasks, groceries, expenses, movies, photos…? This can’t be undone. Settings stay.',
  gCalendars: 'Calendars', gCalHint: 'Choose which calendars to show. “Busy” shows only the time, no titles.', gWriteTo: 'Save new events to',
  'gmode.full': 'Full', 'gmode.busy': 'Busy', 'gmode.off': 'Hide', busy: 'Busy',
  gOtherAccount: 'A calendar from another Google account (e.g. work): in that account, share it with your personal Gmail — it will show up here.',
  gConnect: 'Connect Google', gConnected: 'Connected: {email}', gLastSync: 'Last sync', gSyncNow: 'Sync now',
  gDisconnect: 'Disconnect Google', gShare: 'Show my Google events to my partner', gTasks: 'Sync tasks with Google Tasks',
  gHow: 'Events and tasks sync both ways every 10 minutes. Each of you connects your own Google.',
  gSetup: 'One-time Google Cloud setup (~5 minutes, once for both of you)',
  g1: 'Open console.cloud.google.com and create a project “Family Hub”.',
  g2: '“APIs & Services” → “Library”: enable Google Calendar API and Google Tasks API.',
  g3: '“OAuth consent screen”: External, name Family Hub. Add both Gmail addresses as test users, then “Publish app” — otherwise sign-in expires after 7 days.',
  g4: '“Credentials” → “Create” → “OAuth client ID” → “Web application”. Paste the address below into “Authorized redirect URIs”.',
  g5: 'Copy the Client ID and Client secret. In Supabase: project vdvoem → Edge Functions → Secrets → add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET.',
  g6: 'Come back and tap “Connect Google”. On “app not verified” tap “Advanced” → “Go to”.',
