  'tour.start': 'Start using it',
  'tour.again': 'Take the tour again',
  'tour.welcome': 'Hi, {name}!',
  'tour.welcomeBody': 'This is your shared space for two: chores, shopping, calendar, money, plans and little joys. Whatever one of you adds, the other sees right away. Pick your language first — then we\'ll show the essentials in a minute.',
  'tour.today': 'The Today screen',
  'tour.todayBody': 'The home screen of your day: today\'s events, tasks and shopping, your status ("working", "driving") and mood. Open it in the morning to see what\'s ahead.',
  'tour.tabs': 'Bottom bar and “More”',
  'tour.tabsBody': 'The bottom bar holds the four sections you use most. Everything else (budget, recipes, trips, wishlist and more) lives under “More”.',
  'tour.tabsTip': 'Choose which sections sit at the bottom: Settings → Tab bar.',
  'tour.add': 'Adding things',
  'tour.addBody': 'Every section has a “+” at the top or a quick-add line. Type naturally: “milk, bread, cheese” is sorted into aisles, and “call mum tomorrow at 18:00” becomes a task with a date and time.',
  'tour.addTip': 'Just paste a link — the app fetches the title and picture itself.',
  'tour.swipe': 'Gestures',
  'tour.swipeBody': 'Swipe a row: left to delete, right to mark it done or bought. Tap a row to open its details.',
  'tour.swipeTip': 'Deleted by mistake? An “Undo” button shows up at the bottom for a few seconds.',
  'tour.privacy': 'Private things and surprises',
  'tour.privacyBody': 'Any entry can be “only for me” or a surprise your partner won\'t see until a date you choose. Gifts you prepare from their wishlist are visible only to you.',
  'tour.us': 'The “Us” section',
  'tour.usBody': 'Your shared flame: anything done together counts the day, and your couple mascot and relationship tree grow. No pressure — missed days are forgiven, levels never drop. Mood and small daily quests live here too.',
  'tour.calendar': 'Calendar',
  'tour.calendarBody': 'Shared events and birthdays. Connect Google Calendar and Google Tasks to sync both ways: Settings → Google.',
  'tour.install': 'Add it to your Home Screen',
  'tour.installIos': 'Then it opens like a normal app and can send notifications. In Safari: Share → Add to Home Screen. Open it from the icon and turn on notifications in Settings.',
  'tour.installAndroid': 'Then it opens like a normal app and can send notifications. In Chrome: menu ⋮ → Install app. Open it from the icon and turn on notifications in Settings.',
  'tour.settings': 'Make it yours',
  'tour.settingsBody': 'Settings hold the theme and look, section order, languages, notifications, currency, categories and integrations. Forgot something? You can take this tour again there.',
