  'pair.friendsHint': 'Couples who come through your link count towards your collection.',
  'faq.title': 'Questions and answers',
  'faq.q1': 'Who sees my entries?',
  'faq.a1': 'Everything you add is seen by both of you. An «Only me» entry is yours alone, and a surprise only shows up for your partner on the chosen day — the server itself checks this, not just the app.',
  'faq.q2': 'How do I invite my partner?',
  'faq.a2': 'Settings → Couple & account → «Send your partner an invite». They open the link, sign in — and you\'re one couple. The code can also be typed in.',
  'faq.q3': 'Does it work offline?',
  'faq.a3': 'Yes. Everything is saved on the phone and sent as soon as you\'re back online.',
  'faq.q4': 'Why don\'t notifications arrive?',
  'faq.a4': 'Add the app to your Home Screen, open it from there and turn notifications on: Settings → Notifications & links → Notifications. On iPhone, iOS won\'t let them through otherwise. Or choose delivery to Telegram.',
  'faq.q5': 'What are the flame and the mascot?',
  'faq.a5': 'Every day you do something together, the flame keeps burning and the mascot grows. Freezes cover missed days, and trips pause the flame on their own. You can switch it all off: Settings → Game & rewards.',
  'faq.q6': 'What is the collection?',
  'faq.a6': 'Themes (including countries with their flags), mascots, hats, frames, flames, scenes, postcards and savings designs. Some are open right away, the rest unlock through things you do in the app or are bought once — for both of you at once.',
  'faq.q7': 'Can I export my data?',
  'faq.a7': 'Yes: Settings → Data & help → Data → «Export to file». You get a file with all your entries.',
  'faq.q8': 'How do I delete my data?',
  'faq.a8': 'Settings → Data & help → «Delete my data». Your private entries are deleted and you leave the couple; if nobody else is left in it, everything is deleted.',
