  'faq.title': 'Pytania i odpowiedzi',
  'faq.q1': 'Kto widzi moje wpisy?',
  'faq.a1': 'Wszystko, co dodajecie, widzicie oboje. Wpis „Tylko ja” widzisz tylko ty, a niespodziankę partner zobaczy dopiero w wybranym dniu — pilnuje tego serwer, nie tylko aplikacja.',
  'faq.q2': 'Jak zaprosić partnera?',
  'faq.a2': 'Ustawienia → Para i konto → „Wyślij zaproszenie partnerowi”. Partner otworzy link, zaloguje się — i jesteście jedną parą. Kod można też wpisać ręcznie.',
  'faq.q3': 'Czy działa bez internetu?',
  'faq.a3': 'Tak. Wszystko zapisuje się w telefonie i wyśle się, gdy tylko wróci sieć.',
  'faq.q4': 'Dlaczego nie przychodzą powiadomienia?',
  'faq.a4': 'Dodaj aplikację do ekranu początkowego, otwórz ją stamtąd i włącz powiadomienia: Ustawienia → Powiadomienia i połączenia → Powiadomienia. Na iPhonie bez tego iOS ich nie przepuści. Albo wybierz dostarczanie na Telegram.',
  'faq.q5': 'Co to płomyk i maskotka?',
  'faq.a5': 'Każdego dnia, gdy robicie coś razem, płomyk się pali, a maskotka rośnie. Pominięte dni pokrywają zamrożenia, a w podróży płomyk sam się pauzuje. Wszystko można wyłączyć: Ustawienia → Gra i nagrody.',
  'faq.q6': 'Co to kolekcja?',
  'faq.a6': 'Motywy (także kraje z flagami), maskotki, czapeczki, ramki, płomyki, sceny, kartki i skarbonki. Część jest otwarta od razu, reszta otwiera się za sprawy w aplikacji albo kupuje się raz — od razu dla was obojga.',
  'faq.q7': 'Czy mogę pobrać dane?',
  'faq.a7': 'Tak: Ustawienia → Dane i pomoc → Dane → „Eksportuj do pliku”. Dostaniesz plik ze wszystkimi wpisami.',
  'faq.q8': 'Jak usunąć swoje dane?',
  'faq.a8': 'Ustawienia → Dane i pomoc → „Usuń moje dane”. Usuną się twoje prywatne wpisy i wyjdziesz z pary; jeśli nikt w niej nie zostanie — usunie się wszystko.',
