  'pair.shareText': '{name} te invita a nuestro Family Hub 💞',
  'pair.shareFriends': 'Probad Family Hub, una app compartida para parejas 💞',
  'pair.partnerHint': 'Tu pareja abre el enlace, entra o se registra, y estaréis en la misma pareja.',
  'pair.friendsHint': 'Las parejas que lleguen por vuestro enlace cuentan para vuestra colección.',
  'faq.title': 'Preguntas y respuestas',
  'faq.q1': '¿Quién ve mis entradas?',
  'faq.a1': 'Todo lo que añadís lo veis los dos. Una entrada «Solo yo» solo la ves tú, y una sorpresa tu pareja solo la verá el día elegido: lo comprueba el propio servidor, no solo la app.',
  'faq.q2': '¿Cómo invito a mi pareja?',
  'faq.a2': 'Ajustes → Pareja y cuenta → «Enviar invitación a tu pareja». Abre el enlace, entra y ya sois una pareja. El código también se puede escribir a mano.',
  'faq.q3': '¿Funciona sin internet?',
  'faq.a3': 'Sí. Todo se guarda en el móvil y se envía en cuanto vuelve la conexión.',
  'faq.q4': '¿Por qué no llegan las notificaciones?',
  'faq.a4': 'Añade la app a la pantalla de inicio, ábrela desde allí y activa las notificaciones: Ajustes → Notificaciones y conexiones → Notificaciones. En iPhone, sin esto iOS no las deja pasar. O elige recibirlas en Telegram.',
  'faq.q5': '¿Qué son la llama y la mascota?',
  'faq.a5': 'Cada día que hacéis algo juntos, la llama sigue encendida y la mascota crece. Las congelaciones cubren los días perdidos y en los viajes la llama se pausa sola. Todo se puede desactivar: Ajustes → Juego y premios.',
  'faq.q6': '¿Qué es la colección?',
  'faq.a6': 'Temas (también países con su bandera), mascotas, gorritos, marcos, llamas, escenas, postales y huchas. Una parte está abierta desde el principio; el resto se abre con lo que hacéis en la app o se compra una vez, para los dos a la vez.',
  'faq.q7': '¿Puedo exportar mis datos?',
  'faq.a7': 'Sí: Ajustes → Datos y ayuda → Datos → «Exportar a archivo». Obtendrás un archivo con todas vuestras entradas.',
  'faq.q8': '¿Cómo borro mis datos?',
  'faq.a8': 'Ajustes → Datos y ayuda → «Borrar mis datos». Se borran tus entradas privadas y sales de la pareja; si no queda nadie más, se borra todo.',
