  'pair.shareText': '{name} ti invita nel nostro Family Hub 💞',
  'pair.shareFriends': 'Provate Family Hub, l\'app condivisa per le coppie 💞',
  'pair.partnerHint': 'Il partner apre il link, accede o si registra, e sarete nella stessa coppia.',
  'pair.friendsHint': 'Le coppie che arrivano dal vostro link contano per la vostra collezione.',
  'faq.title': 'Domande e risposte',
  'faq.q1': 'Chi vede le mie voci?',
  'faq.a1': 'Tutto ciò che aggiungete lo vedete entrambi. Una voce «Solo io» la vedi solo tu, e una sorpresa il partner la vedrà solo nel giorno scelto: lo controlla il server stesso, non solo l\'app.',
  'faq.q2': 'Come invito il partner?',
  'faq.a2': 'Impostazioni → Coppia e account → «Invia l\'invito al partner». Apre il link, accede e siete una coppia. Il codice si può anche digitare a mano.',
  'faq.q3': 'Funziona senza internet?',
  'faq.a3': 'Sì. Tutto si salva sul telefono e si invia appena torna la connessione.',
  'faq.q4': 'Perché non arrivano le notifiche?',
  'faq.a4': 'Aggiungi l\'app alla schermata Home, aprila da lì e attiva le notifiche: Impostazioni → Notifiche e collegamenti → Notifiche. Su iPhone, senza questo iOS non le lascia passare. Oppure scegli di riceverle su Telegram.',
  'faq.q5': 'Cosa sono la fiamma e la mascotte?',
  'faq.a5': 'Ogni giorno in cui fate qualcosa insieme la fiamma resta accesa e la mascotte cresce. I congelamenti coprono i giorni saltati e nei viaggi la fiamma va in pausa da sola. Tutto si può spegnere: Impostazioni → Gioco e premi.',
  'faq.q6': 'Cos\'è la collezione?',
  'faq.a6': 'Temi (anche paesi con la loro bandiera), mascotte, cappellini, cornici, fiamme, scene, cartoline e salvadanai. Una parte è aperta subito, il resto si sblocca con quello che fate nell\'app o si compra una volta, per entrambi.',
  'faq.q7': 'Posso esportare i dati?',
  'faq.a7': 'Sì: Impostazioni → Dati e aiuto → Dati → «Esporta su file». Otterrai un file con tutte le vostre voci.',
  'faq.q8': 'Come elimino i miei dati?',
  'faq.a8': 'Impostazioni → Dati e aiuto → «Elimina i miei dati». Si eliminano le tue voci private ed esci dalla coppia; se non resta nessun altro, si elimina tutto.',
